package experiment

import (
	"errors"
	"fmt"
	"path"
	"strings"

	"github.com/jgabor/ktx/internal/benchcontract"
)

const (
	// historicalManifestSchemaVersion archives recorded a plugin generated by
	// the binary; they keep validating without a plugin source identity.
	historicalManifestSchemaVersion = 1
	// currentManifestSchemaVersion archives record the ktx commit and the
	// OpenCode package content hash, and retain the package files.
	currentManifestSchemaVersion = 2
	openCodePluginArchivePath    = "opencode-plugin"
)

// Validation report labels for the plugin identity an archive carries.
const (
	pluginIdentityHistorical = "historical_generated_plugin"
	pluginIdentityVerified   = "commit_and_content_hash"
)

func pluginIdentityLabel(manifest Manifest) string {
	if manifest.SchemaVersion == currentManifestSchemaVersion {
		return pluginIdentityVerified
	}
	return pluginIdentityHistorical
}

func validCommit(commit string) bool {
	return len(commit) == 40 && strings.Trim(commit, "0123456789abcdef") == ""
}

// validateOpenCodePluginIdentity checks the recorded plugin identity without
// reading archive files.
func validateOpenCodePluginIdentity(manifest Manifest) error {
	plugin := manifest.OpenCodePlugin
	if plugin == nil {
		return errors.New("manifest opencode_plugin identity is required")
	}
	if plugin.Package != benchcontract.PluginPackage || !strings.HasPrefix(plugin.Spec, "file:///") {
		return errors.New("manifest opencode_plugin package or spec is invalid")
	}
	if !validCommit(plugin.Commit) {
		return errors.New("manifest opencode_plugin commit must be 40 lowercase hexadecimal characters")
	}
	if manifest.Repository.Commit == nil || *manifest.Repository.Commit != plugin.Commit {
		return errors.New("manifest opencode_plugin commit does not match the repository commit")
	}
	if !validSHA256(plugin.SHA256) {
		return errors.New("manifest opencode_plugin sha256 must be 64 lowercase hexadecimal characters")
	}
	if plugin.Path != openCodePluginArchivePath || len(plugin.Files) == 0 {
		return errors.New("manifest opencode_plugin retained files are missing")
	}
	return nil
}

// validateOpenCodePlugin recomputes the package content hash from the
// retained package files.
func (a *archive) validateOpenCodePlugin(manifest Manifest) error {
	plugin := manifest.OpenCodePlugin
	if plugin == nil {
		return nil
	}
	digests := make(map[string]string, len(plugin.Files))
	for _, name := range plugin.Files {
		if _, duplicate := digests[name]; duplicate {
			return fmt.Errorf("opencode plugin file %q is listed twice", name)
		}
		hash, err := a.hash(path.Join(plugin.Path, name))
		if unsafeArchiveAccess(err) {
			return err
		}
		if err != nil {
			return fmt.Errorf("opencode plugin file %q is missing", name)
		}
		digests[name] = hash
	}
	digest, err := benchcontract.PluginListingSHA256(digests)
	if err != nil {
		return err
	}
	if digest != plugin.SHA256 {
		return errors.New("opencode plugin content hash mismatch")
	}
	return nil
}
